 * @param updatedAtUtc 最近一次配置变更时刻（epoch 毫秒，UTC）
 */
public record ActivityDayConfig(
        String activityId,
        java.sql.Date utcDate,
        int dailyTotal,
        long updatedAtUtc
) {
}

