package com.example.starter.exposure.repo;

import com.example.starter.exposure.domain.ActivityDayConfig;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

/**
 * 活动日预算配置数据访问：activity_day_config（日总额）与 activity_hour_budget（24 小时预算）。
 * 配置整体替换必须在事务内调用，调用方须已持活动行锁。
 */
@Repository
public class ActivityBudgetRepository {

    private final JdbcTemplate jdbc;

    public ActivityBudgetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 查询某 UTC 日的日配置；未配置返回 empty。
     */
    public Optional<ActivityDayConfig> findConfig(String activityId, LocalDate utcDate) {
        return jdbc.query("SELECT activity_id, utc_date, daily_total, updated_at_utc "
                                + "FROM activity_day_config WHERE activity_id = ? AND utc_date = ?",
                        (rs, rowNum) -> new ActivityDayConfig(
                                rs.getString("activity_id"),
                                rs.getDate("utc_date"),
                                rs.getInt("daily_total"),
                                rs.getLong("updated_at_utc")),
                        activityId, java.sql.Date.valueOf(utcDate))
                .stream()
                .findFirst();
    }

    /**
     * 查询某 UTC 日的 24 小时预算，按 hour_of_day 升序；未配置返回空列表。
     */
    public List<Integer> findHourBudgets(String activityId, LocalDate utcDate) {
        return jdbc.query("SELECT budget FROM activity_hour_budget "
                        + "WHERE activity_id = ? AND utc_date = ? ORDER BY hour_of_day",
                (rs, rowNum) -> rs.getInt("budget"),
                activityId, java.sql.Date.valueOf(utcDate));
    }

    /**
     * 整体替换某 UTC 日配置：先删后插日配置与 24 个小时预算。
     * 调用方须已完成全部校验（合计、非负、已开始小时不可下调）并持活动行锁。
     */
    public void replaceConfig(String activityId, LocalDate utcDate, int dailyTotal,
                              List<Integer> hourBudgets, long updatedAtUtc) {
        jdbc.update("DELETE FROM activity_day_config WHERE activity_id = ? AND utc_date = ?",
                activityId, java.sql.Date.valueOf(utcDate));
        jdbc.update("DELETE FROM activity_hour_budget WHERE activity_id = ? AND utc_date = ?",
                activityId, java.sql.Date.valueOf(utcDate));
        jdbc.update("INSERT INTO activity_day_config (activity_id, utc_date, daily_total, updated_at_utc) "
                        + "VALUES (?, ?, ?, ?)",
                activityId, java.sql.Date.valueOf(utcDate), dailyTotal, updatedAtUtc);
        for (int hour = 0; hour < hourBudgets.size(); hour++) {
            jdbc.update("INSERT INTO activity_hour_budget (activity_id, utc_date, hour_of_day, budget) "
                            + "VALUES (?, ?, ?, ?)",
                    activityId, java.sql.Date.valueOf(utcDate), hour, hourBudgets.get(hour));
        }
    }
}

package com.example.starter.exposure.repo;

import com.example.starter.exposure.domain.ActivityHourLedger;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

/**
 * 活动小时额度账目数据访问。加锁/增减方法必须在事务内调用，
 * 依赖 SELECT ... FOR UPDATE 行锁与 CHECK 非负约束保证并发下不超卖、不变负。
 */
@Repository
public class ActivityLedgerRepository {

    private final JdbcTemplate jdbc;

    public ActivityLedgerRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final RowMapper<ActivityHourLedger> MAPPER = (rs, rowNum) -> new ActivityHourLedger(
            rs.getString("activity_id"),
            rs.getDate("utc_date"),
            rs.getInt("hour_of_day"),
            rs.getInt("reserved_count"),
            rs.getInt("confirmed_count"),
            rs.getInt("cancelled_count"),
            rs.getInt("expired_count"));

    private static final String COLUMNS =
            "activity_id, utc_date, hour_of_day, reserved_count, confirmed_count, "
                    + "cancelled_count, expired_count";

    /**
     * 确保小时账目行存在（不存在则以全 0 创建）。
     */
    public void ensureHourRow(String activityId, LocalDate utcDate, int hourOfDay) {
        jdbc.update("INSERT INTO activity_hour_ledger "
                        + "(activity_id, utc_date, hour_of_day, reserved_count, confirmed_count, "
                        + "cancelled_count, expired_count) "
                        + "SELECT ?, ?, ?, 0, 0, 0, 0 WHERE NOT EXISTS ("
                        + "SELECT 1 FROM activity_hour_ledger "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?)",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay,
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
    }

    /**
     * 行锁读取小时账目；账目行不存在返回 empty。
     */
    public Optional<ActivityHourLedger> lockHour(String activityId, LocalDate utcDate, int hourOfDay) {
        return jdbc.query("SELECT " + COLUMNS + " FROM activity_hour_ledger "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ? FOR UPDATE",
                        MAPPER, activityId, java.sql.Date.valueOf(utcDate), hourOfDay)
                .stream()
                .findFirst();
    }

    /**
     * 读取某 UTC 日全部已存在的小时账目，按 hour_of_day 升序；纯读取。
     */
    public List<ActivityHourLedger> listHours(String activityId, LocalDate utcDate) {
        return jdbc.query("SELECT " + COLUMNS + " FROM activity_hour_ledger "
                        + "WHERE activity_id = ? AND utc_date = ? ORDER BY hour_of_day",
                MAPPER, activityId, java.sql.Date.valueOf(utcDate));
    }

    /**
     * 预占占用 +1（reserved_count）。调用方须已持行锁并完成预算校验。
     */
    public void addReserved(String activityId, LocalDate utcDate, int hourOfDay) {
        int rows = jdbc.update("UPDATE activity_hour_ledger SET reserved_count = reserved_count + 1 "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
        if (rows != 1) {
            throw new IllegalStateException("activity hour ledger row missing for "
                    + activityId + " " + utcDate + " " + hourOfDay);
        }
    }

    /**
     * 确认结算：reserved -1，confirmed +1。仅未确认预占可确认，CHECK 约束保证不变负。
     */
    public void settleConfirm(String activityId, LocalDate utcDate, int hourOfDay) {
        int rows = jdbc.update("UPDATE activity_hour_ledger "
                        + "SET reserved_count = reserved_count - 1, confirmed_count = confirmed_count + 1 "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
        if (rows != 1) {
            throw new IllegalStateException("activity hour ledger row missing for "
                    + activityId + " " + utcDate + " " + hourOfDay);
        }
    }

    /**
     * 取消结算：reserved -1，cancelled +1。仅未确认预占可取消。
     */
    public void settleCancel(String activityId, LocalDate utcDate, int hourOfDay) {
        int rows = jdbc.update("UPDATE activity_hour_ledger "
                        + "SET reserved_count = reserved_count - 1, cancelled_count = cancelled_count + 1 "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
        if (rows != 1) {
            throw new IllegalStateException("activity hour ledger row missing for "
                    + activityId + " " + utcDate + " " + hourOfDay);
        }
    }

    /**
     * 过期结算：reserved -1，expired +1。仅未确认预占可过期。
     */
    public void settleExpire(String activityId, LocalDate utcDate, int hourOfDay) {
        int rows = jdbc.update("UPDATE activity_hour_ledger "
                        + "SET reserved_count = reserved_count - 1, expired_count = expired_count + 1 "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
        if (rows != 1) {
            throw new IllegalStateException("activity hour ledger row missing for "
                    + activityId + " " + utcDate + " " + hourOfDay);
        }
    }
}

package com.example.starter.exposure.repo;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;
import java.util.List;

/**
 * 活动日结快照数据访问。快照一旦写入不再修改，后续配置变更不改写已结算日。
 */
@Repository
public class ActivitySnapshotRepository {

    /**
     * 日结快照单小时行视图。
     *
     * @param hourOfDay        UTC 小时，0-23
     * @param confirmedCount   该小时已确认数，单位次
     * @param cancelledCount   该小时已取消数，单位次
     * @param expiredCount     该小时已过期数，单位次
     * @param snapshottedAtUtc 快照固化时刻，epoch 毫秒，UTC
     */
    public record SnapshotHourRow(int hourOfDay, int confirmedCount, int cancelledCount,
                                  int expiredCount, long snapshottedAtUtc) {
    }

    private final JdbcTemplate jdbc;

    public ActivitySnapshotRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 查询某 UTC 日已固化的快照行，按 hour_of_day 升序；未固化返回空列表。
     */
    public List<SnapshotHourRow> findByActivityAndDate(String activityId, LocalDate utcDate) {
        return jdbc.query("SELECT hour_of_day, confirmed_count, cancelled_count, expired_count, "
                        + "snapshotted_at_utc FROM activity_day_snapshot "
                        + "WHERE activity_id = ? AND utc_date = ? ORDER BY hour_of_day",
                (rs, rowNum) -> new SnapshotHourRow(
                        rs.getInt("hour_of_day"),
                        rs.getInt("confirmed_count"),
                        rs.getInt("cancelled_count"),
                        rs.getInt("expired_count"),
                        rs.getLong("snapshotted_at_utc")),
                activityId, java.sql.Date.valueOf(utcDate));
    }

    /**
     * 固化单小时快照（不存在才插入）；并发日结由活动行锁串行化，重复调用不产生重复行。
     */
    public void insertIfAbsent(String activityId, LocalDate utcDate, int hourOfDay,
                               int confirmedCount, int cancelledCount, int expiredCount,
                               long snapshottedAtUtc) {
        jdbc.update("INSERT INTO activity_day_snapshot "
                        + "(activity_id, utc_date, hour_of_day, confirmed_count, cancelled_count, "
                        + "expired_count, snapshotted_at_utc) "
                        + "SELECT ?, ?, ?, ?, ?, ?, ? WHERE NOT EXISTS ("
                        + "SELECT 1 FROM activity_day_snapshot "
                        + "WHERE activity_id = ? AND utc_date = ? AND hour_of_day = ?)",
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay,
                confirmedCount, cancelledCount, expiredCount, snapshottedAtUtc,
                activityId, java.sql.Date.valueOf(utcDate), hourOfDay);
    }
}

