        // 不存在的活动 404
        assertStatus(() -> service.updateBudget("nope",
                new UpdateActivityBudgetRequest("req-b3", DAY, 0, budgets(), 0)), 404);

        // 失败不占键：修正合计后同键成功
        ActivityBudgetResponse ok = service.updateBudget("A",
